-- ============================================================================
-- QI: Quantitative Interpretation joins the catalogue in the Geoscience module.
-- AN APP COURSE: the Suite app is QI Studio (tile qi-studio), with Rock Physics
-- Studio beside it, which run the same engines; the practicals also run in the
-- course's own four explorer panels.
--
-- Catalogue row (module 'geoscience'; path_order 80; prereq_slug
-- 'welldata', owner decision D1 of 2026-10-11; course_type 'app';
-- suite_module left NULL, because the academy key and the Suite module slug
-- agree for geoscience; school left at its default) plus the three capstones
-- and their eighteen graded fields, generated by
-- tools/course-waves/qi/gen_course.py from the ENGINES' OWN RUN
-- (qi_capstone.mjs, qi_capstone_p.mjs and qi_capstone_e.mjs through the
-- teaching lab and the vendored engines), which it refuses to write unless
-- fields.json carries exactly that run's values and the tolerance
-- gradedTolerance.js derives.
--
-- WHAT IS GRADED. Every capstone is a held-out synthetic case (owner decision
-- D2: the members-only videos speak the Ekene answers, so no capstone is set on
-- Ekene), handed to the learner as a case file.
--   TAMBERLO (Associate): the -6 dB low edge and the centroid of the mean
--   spectrum, the local shear slope, the acoustic impedance and Vp/Vs of a
--   stated sample after substitution to brine, and the signed distance of the
--   top interface from the fitted wet trend.
--   QUARVIN (Professional): a Dix interval velocity, Walden's angle, the NMO
--   stretch, the far partial-stack amplitude, the Shuey intercept and the one
--   scale from modelled to seismic amplitude over four wells.
--   DELSHOLM (Expert): a low-frequency model ln(AI), a model-based impedance, a
--   simultaneous-inversion Vp/Vs, the upper bound of a porosity interval, an
--   oil-sand posterior and a closure column height.
--
-- Deep seeds are three separate migrations; the go-live is HELD until a
-- NextGen production upload serves the route /dashboard/apps/qi.
-- NO BEGIN OR COMMIT: apply_qi.sh wraps this file in one transaction.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug, course_type)
values ('qi', 'Quantitative Interpretation', 'geoscience', 80, 'coming_soon', 'welldata', 'app')
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'qi', 'beginner', 'associate',
  'TAMBERLO, a held-out synthetic case (synthetic)',
  'Feasibility: can this seismic see this fluid',
  'TAMBERLO, a held-out synthetic feasibility case (synthetic, written for this capstone; it is not the Ekene field). One case file comes with this capstone: tamberlo_case.json; paste it into the feasibility explorer (Data: paste a case file) and read each value in the view that computes it. The case carries 18 seismic traces of 400 samples every 2 ms, and one well, Tamberlo-1, logged every half foot from 7400 to 7700 ft: the top of the reservoir at 7520 ft, its base at 7640 ft and the oil-water contact at 7590 ft. The stated choices: the mean spectrum of all 18 traces over their whole length with a Tukey taper of 0.1; net sand is Vsh at or below 0.35; the local shear trend is the linear least squares fit of Vs on Vp over the water-leg net sand; the conditions are 195 degF, 3650 psia, a brine salinity of 0.05 (weight fraction of NaCl), oil of 28 API, a gas-oil ratio of 520 scf/stb and a gas gravity of 0.7; the mineral is quartz and clay by Voigt-Reuss-Hill on Vsh and the pore fluid brine and oil by Wood at the sample Sw; the substituted sample is the one at 7561.5 ft, taken to brine (Sw 1) by Gassmann; the cap rock is the 65 ft of log above the top of the reservoir, read as one layer by its means, and the top interface is the cap rock over the mean of the oil-leg net sand; the wet trend takes every sample with Sw below 1 to brine, blocks the log every 16 ft and fits the fluid line through the origin by total least squares; the distance is signed, negative on the hydrocarbon side, and read from that fitted line. Every input a value needs is in the case file or stated here, and no value is a random draw; the engines hold no default for any choice named above. Report six values: the -6 dB low edge of the mean spectrum, in Hz; the centroid of the mean spectrum, in Hz; the slope of the local shear trend, in m/s of Vs per km/s of Vp; the acoustic impedance of the stated sample after substitution, in kg/(m2 s); its Vp/Vs after substitution; and the distance of the top interface from the fitted wet trend. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','tamberlo_low6_hz', 'label','The -6 dB low edge of the case traces'' mean spectrum', 'unit','Hz', 'expected',20.740177079246084, 'tol',5e-07),
    jsonb_build_object('key','tamberlo_centroid_hz', 'label','The centroid of the case traces'' mean spectrum', 'unit','Hz', 'expected',39.79551860667146, 'tol',5e-07),
    jsonb_build_object('key','tamberlo_shear_slope', 'label','The slope of the local shear trend on the water-leg net sand', 'unit','m/s of Vs per km/s of Vp', 'expected',835.402042501606, 'tol',5e-07),
    jsonb_build_object('key','tamberlo_ai_brine', 'label','The acoustic impedance of the stated sample after substitution to brine', 'unit','kg/(m2 s)', 'expected',6066964.699156452, 'tol',5e-07),
    jsonb_build_object('key','tamberlo_vpvs_brine', 'label','The Vp/Vs of the stated sample after substitution to brine', 'unit','ratio', 'expected',1.91832635055991, 'tol',5e-07),
    jsonb_build_object('key','tamberlo_wet_distance', 'label','The signed distance of the top interface from the fitted wet trend', 'unit','distance on the intercept-gradient plane', 'expected',-0.059578965835977195, 'tol',5e-07)
  )
),
(
  'qi', 'intermediate', 'professional',
  'QUARVIN, a held-out synthetic case (synthetic)',
  'From the tie to AVO on the seismic',
  'QUARVIN, a held-out synthetic prestack case (synthetic, written for this capstone; it is not the Ekene field). One case file comes with this capstone: quarvin_case.json; paste it into the prestack explorer (Data: paste a case file). It carries an RMS velocity table, one NMO-corrected CDP gather of 20 offsets every 2 ms from 1100 ms, and the modelled and seismic intercepts and gradients at 4 wells. The stated choices: the Dix layer runs from 880 to 1310 ms; Walden''s angle and the NMO stretch are read at an offset of 1600 m and a time of 1324 ms with the RMS velocity at the stated time; the angle bins have the edges 5, 15, 25, 35 degrees and the far partial stack is bins 2, 3; the Shuey fit takes 2 terms over the partial stacks at 10, 20, 30 degrees at the target sample, 1324 ms; the one scale is the least squares over A and B together, every well. Every input a value needs is in the case file or stated here, and no value is a random draw; the engines hold no default for any choice named above. Report six values: the Dix interval velocity of the stated layer, in m/s; Walden''s angle, in degrees; the NMO stretch, as a fraction; the far partial-stack amplitude at the target sample; the Shuey intercept at the target sample; and the one scale over the wells. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','quarvin_dix_vint', 'label','The Dix interval velocity of the stated layer', 'unit','m/s', 'expected',2820.8223895680444, 'tol',5e-07),
    jsonb_build_object('key','quarvin_walden_deg', 'label','Walden''s angle at the stated offset and time', 'unit','degrees', 'expected',36.52301164233891, 'tol',5e-07),
    jsonb_build_object('key','quarvin_nmo_stretch', 'label','The NMO stretch at the stated offset and time', 'unit','fraction', 'expected',0.12037307727748914, 'tol',5e-07),
    jsonb_build_object('key','quarvin_far_stack_amp', 'label','The far partial-stack amplitude at the target sample', 'unit','trace amplitude', 'expected',26.746679333333333, 'tol',5e-07),
    jsonb_build_object('key','quarvin_shuey_a', 'label','The Shuey intercept at the target sample', 'unit','trace amplitude', 'expected',83.24177796156101, 'tol',5e-07),
    jsonb_build_object('key','quarvin_one_scale', 'label','The one scale from modelled to seismic amplitude over the four wells', 'unit','trace amplitude per unit reflection coefficient', 'expected',1137.2725681690208, 'tol',5e-07)
  )
),
(
  'qi', 'advanced', 'expert',
  'DELSHOLM, a held-out synthetic case (synthetic)',
  'Inversion, properties and the decision',
  'DELSHOLM, a held-out synthetic inversion and prospect case (synthetic, written for this capstone; it is not the Ekene field). One case file comes with this capstone: delsholm_case.json; paste it into the inversion explorer for the first three values and into the prospect explorer for the last three (in each, Data: paste a case file). It carries 3 wells with their low-passed impedance logs in time and horizon times, a target trace A with its full and angle stacks, wavelets and low-frequency models, a position B, calibration samples and a depth grid. The stated choices: the low-frequency model at position B uses inverse distance weighting of power 2 and is read at sample 42; the model-based inversion of trace A uses eps 0.3 and 400 iterations and is read at sample 32; the simultaneous inversion uses eps 0.3, 0.3, 0.3 and 400 iterations and is read at sample 30; the porosity transform''s interval is at the 0.8 level at an impedance of 6550000 kg/(m2 s); the facies model is gaussian with the calibration proportions as priors, read for oil sand at 6380000 kg/(m2 s); the closure is read from the highest mapped node to the spill. Every input a value needs is in the case file or stated here, and no value is a random draw; the engines hold no default for any choice named above. Report six values: the low-frequency model ln(AI) at position B; the model-based acoustic impedance at trace A, in kg/(m2 s); the simultaneous-inversion Vp/Vs at trace A; the upper bound of the porosity interval; the posterior probability of the oil-sand facies; and the closure column height, in ft. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','delsholm_lfm_lnai_b', 'label','The low-frequency model ln(AI) at the stated sample of position B', 'unit','ln of kg/(m2 s)', 'expected',15.628802751655897, 'tol',5e-07),
    jsonb_build_object('key','delsholm_mb_ai', 'label','The model-based acoustic impedance at the stated sample of trace A', 'unit','kg/(m2 s)', 'expected',5925842.253250878, 'tol',1),
    jsonb_build_object('key','delsholm_sim_vpvs', 'label','The simultaneous-inversion Vp/Vs at the stated sample of trace A', 'unit','ratio', 'expected',1.8909602173995903, 'tol',5e-06),
    jsonb_build_object('key','delsholm_phi_q90', 'label','The upper bound of the porosity interval at the stated impedance', 'unit','fraction', 'expected',0.21335715041962583, 'tol',5e-07),
    jsonb_build_object('key','delsholm_p_oil', 'label','The posterior probability of the oil-sand facies at the stated impedance', 'unit','probability', 'expected',0.8099435384728407, 'tol',5e-07),
    jsonb_build_object('key','delsholm_column_ft', 'label','The closure column height of the mapped trap', 'unit','ft', 'expected',139.64800000000105, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
